-- A256: atributos físicos e observação interna por Quadra; não cria preço, disponibilidade, venda, contrato ou financeiro.
create table public.subdivision_block_internal_notes (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete restrict, block_id uuid not null, internal_note text not null check (char_length(trim(internal_note)) between 1 and 280 and internal_note !~* '(\mcpf\M|\mcnpj\M|\mr\$\M|@|\mcontrato\M|\mcobrança\M|\mpagamento\M)'), created_by uuid not null references public.identity_subjects(user_id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint subdivision_block_internal_notes_block_fk foreign key(block_id,organization_id) references public.subdivision_blocks(id,organization_id) on delete restrict, constraint subdivision_block_internal_notes_unique unique(organization_id,block_id));
alter table public.subdivision_block_internal_notes enable row level security;
revoke all on table public.subdivision_block_internal_notes from public,anon,authenticated;

create or replace function public.subdivision_upsert_draft_block_operational_profile_v1(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text,p_development_id uuid,p_block_id uuid,p_sector_reference text,p_block_typology public.subdivision_block_typology,p_internal_note text,p_correlation_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare v_existing uuid; begin perform private.require_active_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code); select target_id into v_existing from public.admin_audit_events where command_name='subdivision_upsert_draft_block_operational_profile_v1' and correlation_id=p_correlation_id and actor_user_id=p_actor_user_id and organization_id=p_organization_id and outcome='allowed' limit 1; if v_existing is not null then return; end if; if not exists(select 1 from public.subdivision_blocks b where b.id=p_block_id and b.organization_id=p_organization_id and b.development_id=p_development_id and b.state='draft'::public.party_lifecycle_state) then raise exception using errcode='42501',message='SUBDIVISION_BLOCK_CONTEXT_DENIED'; end if; update public.subdivision_blocks set sector_reference=p_sector_reference,block_typology=p_block_typology,updated_at=now() where id=p_block_id and organization_id=p_organization_id; if p_internal_note is null then delete from public.subdivision_block_internal_notes where organization_id=p_organization_id and block_id=p_block_id; else insert into public.subdivision_block_internal_notes(organization_id,block_id,internal_note,created_by) values(p_organization_id,p_block_id,btrim(p_internal_note),p_actor_user_id) on conflict(organization_id,block_id) do update set internal_note=excluded.internal_note,created_by=excluded.created_by,updated_at=now(); end if; insert into public.admin_audit_events(correlation_id,actor_user_id,organization_id,command_name,outcome,target_type,target_id,payload_redacted) values(p_correlation_id,p_actor_user_id,p_organization_id,'subdivision_upsert_draft_block_operational_profile_v1','allowed','subdivision_block',p_block_id,jsonb_build_object('module',p_module::text,'purpose_code',btrim(p_purpose_code),'physical_profile_updated',true,'has_internal_note',p_internal_note is not null)); end; $$;
revoke all on function public.subdivision_upsert_draft_block_operational_profile_v1(uuid,uuid,public.operating_module,text,uuid,uuid,text,public.subdivision_block_typology,text,uuid) from public,anon,authenticated;
grant execute on function public.subdivision_upsert_draft_block_operational_profile_v1(uuid,uuid,public.operating_module,text,uuid,uuid,text,public.subdivision_block_typology,text,uuid) to service_role;
